//! Goldstone editor: an Inkscape-style GUI for many-body diagrams.

pub mod app;
mod doc_ops;
pub mod icons;
pub mod keys;
mod menus;
mod panels;
mod pick;
mod plot_dialog;
mod templates_ui;
mod view;

use std::path::PathBuf;

/// Licenses and copyright notices of the third-party crates and fonts
/// compiled into the program (generated by
/// `packaging/third_party_licenses.py`).
pub const THIRD_PARTY_LICENSES: &str = include_str!("../../../THIRD_PARTY_LICENSES.md");

/// Opens the editor window with these files, each in a tab.
pub fn run(paths: Vec<PathBuf>) -> eframe::Result {
    let options = eframe::NativeOptions {
        viewport: egui::ViewportBuilder::default()
            .with_inner_size([1280.0, 820.0])
            .with_min_inner_size([800.0, 500.0])
            .with_title("Goldstone"),
        ..Default::default()
    };
    eframe::run_native(
        "Goldstone",
        options,
        Box::new(move |cc| {
            let mut app = app::GoldstoneApp::new(cc, None);
            app.open_paths(&paths);
            Ok(Box::new(app))
        }),
    )
}

#[cfg(test)]
mod tests {
    #[test]
    fn third_party_licenses_are_embedded() {
        let t = super::THIRD_PARTY_LICENSES;
        for needle in [
            "GUST Font License",
            "SIL Open Font License",
            "UBUNTU FONT LICENCE",
            "### eframe",
            "### typst ",
            "### mitex ",
        ] {
            assert!(
                t.contains(needle),
                "THIRD_PARTY_LICENSES.md lacks {needle:?}"
            );
        }
    }
}
